style.css:
/* Moonlit Seer — Userstyles.org */

/* swap these colors if you want a different palette */
:root {
  --my-night: #101522;
  --my-blue: #202d46;
  --my-lavender: #b9b8e8;
  --my-silver: #e0e4f2;
  --my-text: #e7e9f5;
  --my-muted: #a2acc3;
}

/* midnight atmosphere */
body {
  background: var(--my-night) !important;
  color: var(--my-text) !important;
  font-family: "Segoe UI", sans-serif !important;
}

/* icy accents */
a {
  color: var(--my-lavender) !important;
  transition: color 0.2s ease;
}

a:hover {
  color: var(--my-silver) !important;
}

/* softer controls */
input,
textarea,
select,
button {
  background-color: var(--my-blue) !important;
  color: var(--my-text) !important;
  border-color: #586481 !important;
  border-radius: 8px !important;
}

/* moonlit images */
img {
  border-radius: 10px;
}
